arguments.command:
python3 - <<'EOF'
import re,glob
tot=0; counts={}
for p in sorted(glob.glob('reports/w*.md')):
    t=open(p).read()
    sec=t.split('## Stock on hand')[1].split('## Notes')[0]
    found={}
    for line in sec.splitlines():
        nums=re.findall(r'\d+',line)
        sku=re.search(r'SKU-([A-Z0-9]+)',line)
        if sku and nums:
            if len(nums)!=1: print('MULTINUM',p,line)
            found['SKU-'+sku.group(1)]=int(nums[0])
    if len(found)!=len(set(found)): print('dup',p)
    for k,v in found.items(): counts[k]=counts.get(k,0)+1
    tot+=found.get('SKU-A9',0)
print('A9 total',tot)
print(counts)
EOF
echo '--- notes years'; awk '/^## Notes/{f=1;next} f' reports/*.md | grep -E '\b(19|20)[0-9]{2}\b|year' | sort | uniq -c

